#!/usr/bin/env python3
from pathlib import Path
import base64,gzip,hashlib,py_compile,subprocess,sys
if len(sys.argv)!=2: raise SystemExit("usage: fix_charselect_intro_extraction.py <builder.py>")
b=Path(sys.argv[1]); r=b.with_name("apply_v084_charselect_full.py")
def sh(p): return hashlib.sha256(p.read_bytes()).hexdigest()
if sh(b)!="aefbdec3e9bb0d020a2e525d0fec6fdb5182445515245a622b92d37b8ed0f051": raise SystemExit("unexpected builder baseline")
if sh(r)!="f36376bd0949f1f3d2b2a0ec31a9bebccd8a29df24aff82627c8f4ff5895097e": raise SystemExit("unexpected runtime baseline")
BP=""
RF=""
p=subprocess.run(["patch","--batch","--forward",str(b)],input=gzip.decompress(base64.b64decode(BP)),stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
sys.stdout.buffer.write(p.stdout)
if p.returncode: raise SystemExit("builder fidelity patch failed")
r.write_bytes(gzip.decompress(base64.b64decode(RF)))
if sh(b)!="3dccad884baddc9efbb50f99936fa12ffea6144c7cd9842a485f4fcdb5c4135f": raise SystemExit("builder hash mismatch")
if sh(r)!="764cb05dadb569d9594aae7555e48d28eee7855625314f190e5c55d77128359e": raise SystemExit("runtime hash mismatch")
py_compile.compile(str(b),doraise=True); py_compile.compile(str(r),doraise=True)
print("installed high-fidelity Character Select correction: 256x192 character bank, authentic locks, aligned grid, XA F=1 C=0")